"use client";
import { RiAsterisk } from "@remixicon/react";
import { useState } from "react";
import { ActivityRingsCard } from "../charts/activity-rings-card";
import { MostActiveDaysCard } from "../charts/most-active-days-card";
import { SleepScoreCard } from "../charts/sleep-score-card";
import { StepsCard } from "../charts/steps-card";
import { ImportantAlertsCard, type MedicalAlert } from "../medical/important-alerts-card";
import { PatientInfoCard, type PatientInfoCardProps } from "../medical/patient-info-card";
import { type DashboardTemplateProps, DataDashboard } from "./data-dashboard";

export interface MedicalProfileProps extends DashboardTemplateProps {
  patient?: PatientInfoCardProps;
  alerts?: MedicalAlert[];
}
export function MedicalProfile({ patient, alerts, ...props }: MedicalProfileProps = {}) {
  const [date, setDate] = useState(() => new Date(2026, 6, 10));
  return (
    <DataDashboard
      icon={RiAsterisk}
      tableLayout="fluid"
      tablePageSize={12}
      enableRecordCreation={false}
      {...props}
      kind="medical"
      title="Medical Profile"
      selected="medical"
      action="File a report"
    >
      <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">
        <PatientInfoCard {...patient} />
        <StepsCard />
        <SleepScoreCard />

        <MostActiveDaysCard selectedDate={date} onDateChange={setDate} showActivity={false} />
        <ActivityRingsCard
          selectedDate={date}
          title={`Activity for ${date.toLocaleDateString("en-US", { month: "long", day: "numeric", year: "numeric" })}`}
        />
        <ImportantAlertsCard alerts={alerts} />
      </div>
    </DataDashboard>
  );
}
